<?php
namespace Src\Inventario\Infrastructure\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Src\Auth\Infrastructure\Models\UserEloquentModel;use Src\OrdenTrabajo\Infrastructure\Models\OrdenTrabajoEloquentModel;
class MovimientoInventarioEloquentModel extends Model{use HasUuids;public $timestamps=false;protected $table='movimientos_inventario';protected $fillable=['repuesto_id','orden_id','tipo','cantidad','stock_anterior','stock_resultante','costo_unitario','motivo','movimiento_origen_id','registrado_por'];protected function casts():array{return['cantidad'=>'decimal:3','stock_anterior'=>'decimal:3','stock_resultante'=>'decimal:3','costo_unitario'=>'decimal:2','created_at'=>'immutable_datetime'];}public function repuesto():BelongsTo{return$this->belongsTo(RepuestoEloquentModel::class,'repuesto_id');}public function orden():BelongsTo{return$this->belongsTo(OrdenTrabajoEloquentModel::class,'orden_id');}public function usuario():BelongsTo{return$this->belongsTo(UserEloquentModel::class,'registrado_por');}public function origen():BelongsTo{return$this->belongsTo(self::class,'movimiento_origen_id');}}
